// gta6-meme-x-01 entry: "Post a GTA 6 meme on X" (make.fun).
//
// Node 22, standard library only. No network, no wall clock, no files
// outside this repository: two runs write the same bytes.
//
// What it does:
//   1. Reads POST.json from the repository (MAKEFUN_BOT_DIR, default /bot),
//      checks it parses as a JSON object with a `url` string, and warns
//      when the url is not yet a real X post address (the placeholder
//      the repository ships with is replaced once the meme is posted).
//   2. Copies POST.json to the output directory (MAKEFUN_OUTPUT_DIR,
//      default /output), where the gate reads it.
//   3. Writes the meme picture itself to the output directory as
//      meme.jpg, from the JPEG bytes embedded below (the same picture
//      posted on X: the make.fun ghost driving a pink convertible
//      through a Vice City sunset, "WAITED 13 YEARS / WORTH EVERY
//      SECOND", with a make.fun billboard).
//
// Run it the way the grader does:
//   mkdir -p out && MAKEFUN_BOT_DIR=. MAKEFUN_OUTPUT_DIR=out node main.ts

import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const BOT_DIR = process.env.MAKEFUN_BOT_DIR ?? '/bot';
const OUTPUT_DIR = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

const POST_FILE = 'POST.json';
const MEME_FILE = 'meme.jpg';

