function fail(message: string): never {
  console.error(`gta6-meme-x-01: ${message}`);
  process.exit(1);
}

// An X post address as the house reads one: x.com or twitter.com,
// optional www. or mobile. prefix, /status/ (or /statuses/, or
// /i/web/status/) followed by the post id digits only.
function isPostAddress(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  return /^https:\/\/(www\.|mobile\.)?(x\.com|twitter\.com)\/(i\/web\/)?status(es)?\/[0-9]{1,19}$/.test(
    value,
  );
}

function main(): void {
  const postPath = join(BOT_DIR, POST_FILE);

  let raw: string;
  try {
    raw = readFileSync(postPath, 'utf8');
  } catch (err) {
    fail(`could not read ${postPath}: ${(err as Error).message}`);
  }

  let post: unknown;
  try {
    post = JSON.parse(raw);
  } catch (err) {
    fail(`${POST_FILE} is not valid JSON: ${(err as Error).message}`);
  }
  if (typeof post !== 'object' || post === null || Array.isArray(post)) {
    fail(`${POST_FILE} must be a JSON object with a "url" field`);
  }
  const url = (post as { url?: unknown }).url;
  if (typeof url !== 'string') {
    fail(`${POST_FILE} has no "url" string field`);
  }
  if (!isPostAddress(url)) {
    console.error(
      `gta6-meme-x-01: warning: ${POST_FILE} url is not a real X post address yet: ${url}`,
    );
  }

  mkdirSync(OUTPUT_DIR, { recursive: true });
  copyFileSync(postPath, join(OUTPUT_DIR, POST_FILE));

  const memeBytes = Buffer.from(MEME_JPEG_BASE64, 'base64');
  if (memeBytes.length === 0) {
    fail('embedded meme picture decoded to zero bytes');
  }
  writeFileSync(join(OUTPUT_DIR, MEME_FILE), memeBytes);

  console.log(
    `gta6-meme-x-01: wrote ${POST_FILE} and ${MEME_FILE} (${memeBytes.length} bytes) to ${OUTPUT_DIR} for ${url}`,
  );
}

main();
